function table(){let headers,rows;if(group==='station'){headers=['대안','용량 명/분','최대 대기 명','잔여 보도 m'];rows=groupScenes().map(s=>{let q=K.queue(s.metrics.width,+$('flow').value,+$('demand').value,time);return[s.variant,fmt(q.capacity,0),fmt(q.max,0),fmt(s.metrics.remaining)]})}else if(group==='home'){headers=['대안','단높이 mm','디딤폭 지표 mm','머리 공간'];rows=groupScenes().map(s=>[s.variant,fmt(s.metrics.rise*1000,0),fmt(s.metrics.tread*1000,0),'미판정'])}else if(group==='park'){headers=['대안','체류 ㎡','운영인원','연속 접근'];rows=groupScenes().map(s=>[s.variant,fmt(s.metrics.usable_area),Math.floor(s.metrics.usable_area/+$('area').value),s.metrics.access?'개념 연결':'단절'])}else{headers=['결과','객체 수','통과 완료','내부 잔류','외부 대기'];let r=replay(),m=r.metrics;rows=[[customResults.has(scene.id)?'현재 사용자 배치':'기본 사전계산',m.obstacle_count||0,m.completed,m.inside,m.outside]]} $('thead').innerHTML='<tr>'+headers.map(a=>'<th>'+a+'</th>').join('')+'</tr>';$('tbody').innerHTML=rows.map(row=>'<tr>'+row.map(a=>'<td>'+a+'</td>').join('')+'</tr>').join('')}
function chart(){let c=$('smallChart'),ctx=c.getContext('2d'),dpr=Math.min(1.5,window.devicePixelRatio||1),W=c.clientWidth,H=115;c.width=W*dpr;c.height=H*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#f4f8f5';ctx.fillRect(0,0,W,H);ctx.font='11px Malgun Gothic';let curves=[],labels=[];if(group==='station'){let m=stats();curves=[m.history];labels=['대기 인원']}else if(group==='crowd'){let r=replay();curves=[1,2,3].map(j=>r.series.map(a=>a[j]));labels=['통과 누적','내부 인원','외부 대기']}else{let vals=group==='home'?groupScenes().map(s=>s.metrics.tread*1000):[2,4,6,8].map(a=>Math.floor(scene.metrics.usable_area/a)),max=Math.max(...vals)*1.2;vals.forEach((v,i)=>{let x=30+i*(W-40)/vals.length,h=v/max*70;ctx.fillStyle='#91bcb1';ctx.fillRect(x,95-h,(W-50)/vals.length*.65,h);ctx.fillStyle='#335c61';ctx.fillText(fmt(v,0),x,88-h);ctx.fillText(group==='home'?'H'+(i+1):[2,4,6,8][i]+'㎡/명',x,110)});return}let max=Math.max(1,...curves.map(a=>Math.max(...a)))*1.15;curves.forEach((v,j)=>{ctx.strokeStyle=['#147e7a','#6c8eb5','#d68a52'][j];ctx.lineWidth=1.8;ctx.beginPath();v.forEach((n,i)=>{let x=30+i/(v.length-1)*(W-50),y=95-n/max*70;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.fillText(labels[j],30+j*90,14)});ctx.fillStyle='#6a8281';ctx.fillText('0초',30,110);ctx.fillText(group==='station'?'300초':'240초',W-55,110)}
function setGroup(g){cancelSimulation();group=g;scene=DATA.scenes.find(s=>s.group===g&&(g!=='crowd'||s.id==='C3'));$('variant').innerHTML=groupScenes().map(s=>`<option value="${s.id}">${s.variant}</option>`).join('');$('variant').value=scene.id;document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group===g));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==g);time=g==='station'?60:g==='home'?0:42;$('time').max=g==='station'?299.9:g==='crowd'?239.5:g==='home'?160:180;zoom=1;dirty=false;selected=null;$('progress').textContent='';if(g==='crowd'&&(obstacles.length||+$('crowdDemand').value!==1)&&!customResults.has(scene.id)){dirty=true;playing=false}setPlaying(playing);rebuild();updateStats();listObstacles()}
function setPlaying(value){playing=value;$('motion').textContent=playing?'일시정지':'재생';$('motion').classList.toggle('active',playing)}
function tick(stamp){let dt=lastStamp?Math.min(.5,(stamp-lastStamp)/1000):0;lastStamp=stamp;if(playing){time+=dt*+$('playSpeed').value;let max=+$('time').max;if(time>max)time=0;draw();if(group==='station'&&Math.floor(time)!==Math.floor(time-dt*+$('playSpeed').value))updateStats()}requestAnimationFrame(tick)}
function cancelSimulation(){if(workerURL){URL.revokeObjectURL(workerURL);workerURL=null}if(worker){worker.terminate();worker=null;runId++}$('runSim').disabled=false}
function markDirty(){cancelSimulation();dirty=true;customResults.clear();setPlaying(false);$('progress').textContent='배치 변경 · 재계산 필요';rebuild();listObstacles();updateStats()}
function canPlace(o,ignoreId=null){let f=K.footprint(o);if(f.x<.25||f.y<0||f.x+f.w>15.75||f.y+f.d>6)return false;let w=scene.metrics.width,lo=(6-w)/2,hi=lo+w;if(f.x<10&&f.x+f.w>6&&(f.y<lo||f.y+f.d>hi))return false;return !obstacles.some(other=>other.id!==ignoreId&&(()=>{let b=K.footprint(other);return f.x<b.x+b.w&&f.x+f.w>b.x&&f.y<b.y+b.d&&f.y+f.d>b.y})())}
function addObstacle(type,x,y,rotation=0){let o={id:nextObstacleId++,type,x,y,rotation};if(!Object.prototype.hasOwnProperty.call(K.OBSTACLE,type)||!canPlace(o)){ $('progress').textContent='이 위치는 통로 밖이거나 다른 객체와 겹칩니다.';return false}obstacles.push(o);selected=o.id;markDirty();return true}
function listObstacles(){let list=$('obstacleList');list.innerHTML='';for(let o of obstacles){let row=document.createElement('div');row.className='obstacle-item'+(selected===o.id?' selected':'');let name=document.createElement('span');name.textContent=K.OBSTACLE[o.type].name+' · '+fmt(o.x)+', '+fmt(o.y)+'m';let choose=document.createElement('button');choose.textContent='선택';choose.onclick=()=>{selected=o.id;listObstacles();rebuild();draw()};let remove=document.createElement('button');remove.textContent='삭제';remove.onclick=()=>{obstacles=obstacles.filter(a=>a.id!==o.id);if(selected===o.id)selected=null;markDirty()};row.append(name,choose,remove);list.appendChild(row)}}
function randomize(){let rand=K.rng(+$('seed').value||11),count=K.clamp(+$('randomCount').value||5,1,20),types=Object.keys(K.OBSTACLE),added=0;for(let tries=0;tries<500&&added<count;tries++){let type=types[Math.floor(rand()*types.length)],o={id:nextObstacleId++,type,x:1+rand()*14,y:.5+rand()*5,rotation:rand()<.5?0:90};if(canPlace(o)){obstacles.push(o);added++}}selected=null;markDirty();$('progress').textContent=added+'개 추가 · 재계산을 눌러 주세요.'}
function runSimulation(){if(group!=='crowd')return;cancelSimulation();let id=++runId;setPlaying(false);$('runSim').disabled=true;$('progress').textContent='새 배치의 보행 경로와 점유 영역을 계산하고 있습니다…';let config={layout:scene.metrics.width===6?'open':'bottleneck',openWidth:6,width:scene.metrics.width,managed:scene.metrics.managed,metering:scene.metrics.metering,demand:+$('crowdDemand').value,seed:+$('seed').value||11,obstacles:JSON.parse(JSON.stringify(obstacles))};try{workerURL=URL.createObjectURL(new Blob([WORKER_SOURCE],{type:'application/javascript'}));worker=new Worker(workerURL);worker.onmessage=e=>{if(id!==runId)return;if(workerURL){URL.revokeObjectURL(workerURL);workerURL=null}if(e.data.progress!==undefined){$('progress').textContent='인파 계산 '+e.data.progress+'%';return}if(e.data.error){$('progress').textContent='계산 실패: '+e.data.error;$('runSim').disabled=false;worker.terminate();worker=null;return}simulation=e.data.result;customResults.set(scene.id,simulation);dirty=false;time=42;selected=null;$('runSim').disabled=false;$('progress').textContent='새 배치 계산 완료 · '+simulation.metrics.arrived+'명 유입 · '+simulation.metrics.obstacle_count+'개 장애물 반영';worker.terminate();worker=null;setPlaying(true);rebuild();updateStats()};worker.onerror=e=>{$('progress').textContent='계산 작업을 시작하지 못했습니다: '+e.message;$('runSim').disabled=false};worker.postMessage(config)}catch(e){$('progress').textContent='계산 시작 오류: '+e.message;$('runSim').disabled=false}}
