canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)drag.moved=true;if(group!=='crowd'||$('editMode').value==='inspect'){yaw-=dx*.006;pitch=K.clamp(pitch+dy*.005,.15,Math.PI/2-.01);drag.x=e.clientX;drag.y=e.clientY;draw()}};canvas.onpointerup=e=>{if(drag&&!drag.moved)editClick(e);drag=null};canvas.onwheel=e=>{e.preventDefault();zoom=K.clamp(zoom*Math.exp(-e.deltaY*.001),.5,3);draw()};
