function cachedBus(policy){let config=busConfig(policy),key=JSON.stringify(config);if(!transitCache.has(key)){transitCache.set(key,TransportCore.busSim(config));if(transitCache.size>16)transitCache.delete(transitCache.keys().next().value)}return transitCache.get(key)}
function liftPeople(){let c=liftConfig(),r=TransportCore.lift(c),pts=r.points;if($('liftDisplay').value==='rated')pts=Array.from({length:13},(_,i)=>({x:.28+(i%3)*.52,y:.16+Math.floor(i/3)*.27,rotation:0,dx:c.bodyWidth,dy:.32}));return pts.map((p,i)=>({id:i,type:p.wheelchair?4:i%4===0?2:1,p:[p.x,p.y,.025],heading:p.wheelchair?Math.PI/2:Math.PI/2+p.rotation,distance:0,walking:false,bodyWidth:p.wheelchair?.75:c.bodyWidth,bodyDepth:p.wheelchair?1.20:.32}))}
