for(let id of ['liftBody','liftGap','liftMass','liftBag','liftDisplay','busStanding','busLoiter','busBody','busGap','busWheelchair','busStrict'])$(id).oninput=()=>{rebuild();updateStats()};
function aggregateDirection(rows){const mean=a=>a.reduce((s,v)=>s+v,0)/a.length,sd=a=>Math.sqrt(a.reduce((s,v)=>s+(v-mean(a))**2,0)/(a.length-1)),keys=['throughput_person_min','mean_population_net_speed','mean_population_path_speed','mean_outside_wait_s','completed','inside','outside'];return[0,1,2].map(i=>{let rs=rows.filter(r=>r.condition===i+1),s={condition:i+1,label:directionData.labels[i],runs:rs.length};for(let key of keys){let a=rs.map(r=>r[key]);s[key]={mean:mean(a),sd:sd(a),min:Math.min(...a),max:Math.max(...a)}}return s})}
$('runDirection').onclick=()=>{cancelSimulation();const id=++runId,seeds=directionData.seeds,modes=directionData.modes,demand=+$('directionDemand').value;setPlaying(false);$('runDirection').disabled=true;$('directionProgress').textContent='30개 실험을 계산합니다…';let code=WORKER_SOURCE+'\nself.onmessage=function(e){try{var rows=[],examples=[];for(var i=0;i<3;i++)for(var j=0;j<e.data.seeds.length;j++){var r=MicroCore.simulate({layout:"open",openWidth:4,width:4,ratePeak:80,rateNormal:40,laneMode:e.data.modes[i],demand:e.data.demand,seed:e.data.seeds[j],record:j===0});rows.push(Object.assign({condition:i+1,seed:e.data.seeds[j]},r.metrics));if(j===0)examples.push(r);self.postMessage({progress:Math.round((i*e.data.seeds.length+j+1)/(3*e.data.seeds.length)*100)})}self.postMessage({batch:{rows:rows,examples:examples}})}catch(error){self.postMessage({error:error.message})}};';workerURL=URL.createObjectURL(new Blob([code],{type:'application/javascript'}));worker=new Worker(workerURL);worker.onmessage=e=>{if(id!==runId)return;if(workerURL){URL.revokeObjectURL(workerURL);workerURL=null}if(e.data.progress!==undefined){$('directionProgress').textContent='비교 계산 '+e.data.progress+'%';return}if(e.data.error){$('directionProgress').textContent=e.data.error;$('runDirection').disabled=false;cancelSimulation();return}let r=e.data.batch;directionData={...directionData,configuration:{...directionData.configuration,demand_multiplier:demand,effective_peak_person_min:80*demand,effective_normal_person_min:40*demand},rows:r.rows,summaries:aggregateDirection(r.rows)};DATA.scenes.filter(s=>s.group==='direction').forEach((s,i)=>{s.replay=r.examples[i];s.metrics=r.examples[i].metrics});$('runDirection').disabled=false;$('directionProgress').textContent='세 조건10회 계산 완료 · 수요 '+demand+'배';cancelSimulation();time=42;setPlaying(true);updateStats()};worker.onerror=e=>{$('directionProgress').textContent='계산 오류: '+e.message;$('runDirection').disabled=false;cancelSimulation()};worker.postMessage({seeds,modes,demand})};
// Fit the model to the available viewport rather than a fixed maximum page width.
