function motionResult(){let config=group==='station'?{width:scene.metrics.width,flow:+$('flow').value,demand:+$('demand').value,share:+$('stationShare').value/100}:group==='park'?{id:scene.id,count:+$('parkCount').value,reverse:$('parkFlow').value==='reverse'}:group==='lift'?{...liftConfig(),size:scene.metrics.size}:group==='bus'?busConfig():null;if(!config)return null;let key=group+JSON.stringify(config);if(!motionCache.has(key)){let r=group==='station'?MotionV3.station(config):group==='park'?MotionV3.park(scene,config.count,config.reverse):group==='lift'?MotionV3.liftCycle(config):BusV3.simulate(config);if(motionCache.size>12)motionCache.delete(motionCache.keys().next().value);motionCache.set(key,r)}return motionCache.get(key)}
people=function(){if(['station','park','bus'].includes(group)||group==='lift'&&$('liftDisplay').value==='cycle')return MotionV3.sample(motionResult(),time);if(group==='lift'){let m=MotionV3.lift({...liftConfig(),size:scene.metrics.size});return m.points.map((p,i)=>({id:i,type:1,p:[p.x,p.y,.025],heading:Math.PI/2+p.rotation,distance:0,walking:false,bodyWidth:m.bodyWidth,bodyDepth:.32}))}return priorV3.people()};
