 if(group==='park'){$('parkText').textContent=$('parkCount').value+'명';$('areaText').textContent=$('area').value+'㎡/명';cards([[m.people+'명','표시 인원'],[row[1]+'명','현재 상부 공간'],[row[2]+'명','현재 이동 중'],[m.upperVisits+' / '+m.lowerVisits,'360초 상부 진입 / 하부 복귀']]);$('status').textContent='하부 산책로–계단–상부–경사로를 연결한 순환 동선입니다. 반대 방향 사람과 이동 구간이 겹치면 기다립니다. 휠체어는 계단을 이용하지 않으며 경사로 없는 안에서는 하부에 머뭅니다.'}
