 if(group==='bus'){$('busStandingText').textContent=$('busStanding').value+'명';$('busLoiterText').textContent=$('busLoiter').value+'%';$('busBodyText').textContent=$('busBody').value+'cm';$('busGapText').textContent=$('busGap').value+'cm';cards([[row[6]+' / 6','현재 정류장'],[row[1]+' / '+row[2]+'명','현재 앞 / 뒤 인원'],[row[5]+' / '+row[4]+'명','누적 승차 / 하차'],[row[3]+'명','외부 대기']]);$('status').textContent='전방은 +X, 운전석은 좌측, 출입문은 우측입니다. 뒤쪽은 좌우 2인 좌석이며 좌석·넓은 입석 공간에 분산합니다. 정류장별 수요와 목적지를 가진 승객이 앞문으로 타고 중앙문으로 내립니다.'}
