const v4Prior={setGroup,updateStats,draw,people,stats,motionResult,replay,rebuild,table,chart,extraMesh};
let v4Crowd=V4_INITIAL_CROWD,v4LiftStudy=V4_INITIAL_LIFT,v4Selected=0,v4LiftStale=false,v4CrowdStale=false;
const v4Cache=new Map(),v4Colors=['#247f78','#cb9344','#6c83ad','#a65b79','#548a4e','#7d6c9f'];
function v4LiftConfig(){return{size:scene.metrics.size,count:+$('v4LiftN').value||scene.metrics.rated,bodyWidth:+$('liftBody').value/100,bodyDepth:+$('v4Depth').value/100,gap:+$('liftGap').value/100,mass:K.clamp(+$('liftMass').value||75,40,140),bag:K.clamp(+$('liftBag').value||0,0,30),policy:$('v4LiftPolicy').value||'random',seed:+$('seed').value||11,compliance:K.clamp(+$('v4Compliance').value/100,0,1),boardingHeadway:K.clamp(+$('v4Headway').value||1.3,.8,3),hesitation:K.clamp(+$('v4Hesitation').value,0,5),walkSpeed:K.clamp(+$('v4WalkSpeed').value||.65,.3,1.2)}}
function v4BusConfig(policy=scene.metrics.policy){return{count:+$('v4BusN').value||47,demand:+$('v4BusDemand').value||20,bodyWidth:+$('busBody').value/100,gap:+$('busGap').value/100,policy,seed:19}}
function v4Cached(kind,config){let key=kind+JSON.stringify(config);if(!v4Cache.has(key)){let r=kind==='lift'?LiftMultiV4.simulate(config):CapacityV4.bus(config);if(v4Cache.size>6)v4Cache.delete(v4Cache.keys().next().value);v4Cache.set(key,r)}return v4Cache.get(key)}
motionResult=function(){return group==='lift'?v4Cached('lift',v4LiftConfig()):group==='bus'?v4Cached('bus',v4BusConfig()):v4Prior.motionResult()};
replay=function(){return group==='crowd'&&v4Crowd.examples[v4Selected]?v4Crowd.examples[v4Selected]:v4Prior.replay()};
people=function(){return group==='lift'||group==='bus'?MotionV3.sample(motionResult(),time):v4Prior.people()};
stats=function(){if(group==='lift'||group==='bus')return motionResult().metrics;if(group==='crowd'){let s=v4Crowd.summaries[v4Selected],m=replay().metrics;return{...m,throughput_person_min:s.throughput_person_min.mean,mean_population_net_speed:s.mean_population_net_speed.mean,average_density:s.average_density.mean}}return v4Prior.stats()};
rebuild=function(){if(group!=='crowd'||dirty||!v4Crowd.examples[v4Selected]){v4Prior.rebuild();return}let edit=obstacles;obstacles=v4Crowd.examples[v4Selected].config.obstacles||[];v4Prior.rebuild();obstacles=edit};
function v4Data(){if(group==='crowd')return{summaries:v4Crowd.summaries,keys:['throughput_person_min','mean_population_net_speed','average_density'],names:['통행량 · 명/분','평균 전진속도 · m/s','평균 밀도 · 명/㎡'],stale:dirty||v4CrowdStale,title:'동일 입력의 조건별 평균 ± 표준편차 · '+v4Crowd.configuration.seeds.length+'회 / 조건'};if(group==='lift')return{summaries:v4LiftStudy.summaries,keys:['total_s','reboards','door_blocked_s'],names:['총 소요시간 · 초','임시 하차 후 재탑승 · 회','문 앞 차단 관련 시간 · 초'],stale:v4LiftStale,title:'동일 인원·목적층 비교 · '+v4LiftStudy.configuration.count+'명 · '+v4LiftStudy.configuration.seeds.length+'회 / 조건'};
 if(group==='bus'){let cfg=v4BusConfig();return{summaries:['loiter','disperse','yield'].map((policy,i)=>{let m=v4Cached('bus',{...cfg,policy}).metrics;return{label:['앞쪽 체류','실내 분산','하차 우선 + 분산'][i],boarded:{mean:m.boarded,sd:0},alighted:{mean:m.alighted,sd:0},leftBehind:{mean:m.leftBehind,sd:0}}}),keys:['boarded','alighted','leftBehind'],names:['6회 누적 승차 · 명','6회 누적 하차 · 명','이전 정류장 미승차 · 명'],title:'만원 초기 상태 '+cfg.count+'명 · 단일 시드 가정 실험',stale:false}}return null}
function v4Bars(canvasEl,data){if(!data)return;let c=canvasEl,W=Math.max(240,c.clientWidth||700),H=c.clientHeight||128,dpr=Math.min(1.5,window.devicePixelRatio||1);c.width=W*dpr;c.height=H*dpr;let x=c.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,W,H);x.fillStyle='#f7faf8';x.fillRect(0,0,W,H);x.font='10px Malgun Gothic';for(let k=0;k<3;k++){let left=k*W/3+8,width=W/3-20,base=H-19,top=23,height=base-top,key=data.keys[k],max=Math.max(.001,...data.summaries.map(s=>s[key].mean+s[key].sd))*1.16,n=data.summaries.length,bw=Math.max(7,(width-22)/n*.58);x.fillStyle='#32525a';x.fillText(data.names[k],left,12);x.strokeStyle='#b7cac4';x.beginPath();x.moveTo(left+8,top);x.lineTo(left+8,base);x.lineTo(left+width,base);x.stroke();x.fillStyle='#647d7e';x.fillText('0',left,base+4);for(let i=0;i<n;i++){let v=data.summaries[i][key],cx=left+17+(i+.5)*(width-22)/n,h=v.mean/max*height;x.fillStyle=v4Colors[i];x.fillRect(cx-bw/2,base-h,bw,h);x.strokeStyle='#466267';x.beginPath();x.moveTo(cx,base-(v.mean-v.sd)/max*height);x.lineTo(cx,base-(v.mean+v.sd)/max*height);x.stroke();x.fillStyle='#31515a';x.fillText(v.mean.toFixed(key.includes('density')||key.includes('speed')?2:1),cx-bw*.75,Math.max(22,base-h-4));x.fillText(String.fromCharCode(65+i),cx-3,H-4)}}}
