/* v5: compact, persistent state and linked geometry/replay; four supported studies. */
const v5Prior={setGroup,draw,updateStats,people,stats,rebuild,table,chart,extraMesh};
const V5_DEFAULT_LAYOUT=[{id:1,type:'tree',x:4.0,y:1.1,rotation:0},{id:2,type:'scooter',x:7.4,y:2.2,rotation:90},{id:3,type:'bike',x:10.5,y:4.7,rotation:0},{id:4,type:'sign',x:12.6,y:1.5,rotation:0},{id:5,type:'tree',x:2.0,y:4.7,rotation:0}];
let v5Stairs=null,v5LiftRenderers=[],v5LiftSnapshots=[],v5LiftClock=0,v5LiftLast=0;
let v5LastSaved='';function v5Persist(){let value=JSON.stringify(obstacles);if(value===v5LastSaved)return;try{localStorage.setItem('microspace-layout-v5',value);v5LastSaved=value}catch(e){}}
function v5Restore(){try{let raw=localStorage.getItem('microspace-layout-v5');if(raw){let a=JSON.parse(raw);if(Array.isArray(a)&&a.every(o=>K.OBSTACLE[o.type]&&Number.isFinite(o.x)&&Number.isFinite(o.y)))return a}}catch(e){}return JSON.parse(JSON.stringify(V5_DEFAULT_LAYOUT))}
const v5Dirty=markDirty;markDirty=function(){v5Dirty();v5Persist();$('v4Replay').disabled=true;$('v4CrowdProgress').textContent='배치 변경: 비교 계산 후 재생 조건이 갱신됩니다.'};
function v5Sync(){if(group!=='crowd')return;$('v4Replay').value=String(v4Selected);$('v4Replay').disabled=dirty;let rr=v4Crowd.examples[v4Selected];if(rr){let actual=rr.config.obstacles||[];$('v5LayoutState').textContent=(dirty?'편집 중 · 재계산 필요':v4Crowd.conditions[v4Selected].label)+' · 화면 장애물 '+(dirty?obstacles.length:actual.length)+'개';}v5Persist()}
const v5Fill=v4FillReplay;v4FillReplay=function(){v5Fill();$('v4Replay').value=String(v4Selected);$('v4Replay').disabled=dirty};
$('v4Replay').onchange=()=>{v4Selected=Number($('v4Replay').value);if(!v4Crowd.examples[v4Selected])return;selected=null;rebuild();v5Sync();updateStats()};
$('v5DefaultLayout').onclick=()=>{obstacles=JSON.parse(JSON.stringify(V5_DEFAULT_LAYOUT));nextObstacleId=100;selected=null;markDirty()};
$('v5SaveDefault').onclick=()=>{v5Persist();$('v5LayoutState').textContent='이 브라우저의 기본 배치로 저장했습니다.'};
// Drag rotates in every edit mode. Only a short click edits; right drag always inspects.
canvas.oncontextmenu=e=>e.preventDefault();canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)};
canvas.onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)drag.moved=true;if(drag.moved){yaw-=dx*.006;pitch=K.clamp(pitch+dy*.005,.15,Math.PI/2-.01);draw()}drag.x=e.clientX;drag.y=e.clientY};
canvas.onpointerup=e=>{if(drag&&!drag.moved&&e.button!==2)editClick(e);drag=null};canvas.onpointercancel=()=>drag=null;
$('obstacleToggle').onclick=()=>{let open=$('obstacleEditor').hidden;$('obstacleEditor').hidden=!open;$('obstacleToggle').textContent=open?'장애물 편집 접기':'장애물 편집 열기';$('editMode').value='inspect';$('crowdDemand').hidden=false;$('stageHelp').textContent='드래그 회전 · 휠 확대 · 짧게 클릭하여 편집'};
$('editMode').onchange=()=>{$('stageHelp').textContent='모든 모드: 드래그 회전 · 휠 확대 / 짧게 클릭: '+({inspect:'보기',place:'추가',move:'선택·이동',delete:'삭제'}[$('editMode').value])};
function v5BuildStairs(){v5Stairs=StairV5.solve({width:+$('v5SW').value,depth:+$('v5SD').value,height:+$('v5SH').value,clearWidth:+$('v5SB').value});let kind=$('v5StairKind').value,g=StairV5.objects(v5Stairs,kind),a=v5Stairs.alternatives.find(a=>a.kind===kind);scene={id:'H5',group:'home',title:'구옥 계단 · 치수 적합성',variant:kind==='u'?'U자형':'회전계단',objects:g.objects,route:g.route,metrics:{...a,tread:a.tread,rise:a.rise}};rebuild();$('time').max=160;updateStats()}
for(let id of ['v5SW','v5SD','v5SH','v5SB'])$(id).oninput=()=>{if(group==='home')v5BuildStairs()};$('v5StairKind').onchange=()=>v5BuildStairs();
