function v6HomeStats(){let r=v6StairResult(),ps=people(),on=ps.filter(a=>a.state==='walking').length;$('title').textContent='계단 배치 · 공간 치수와 보행 검토';$('hud').textContent='이용자 '+r.metrics.count+'명 · 계단 이동 '+on+'명 · 대기 '+(r.metrics.count-on)+'명\n'+r.metrics.passing+' · '+({up:'올라가기',down:'내려가기',both:'양방향'}[r.metrics.mode])+'\n중앙 난간 분리 · 상·하부 층 연결';$('v6StairCountText').textContent=$('v6StairCount').value+'명';$('note').textContent='중앙 난간은 두 계단 사이에 두고 참을 가로지르지 않습니다. 좁은 U자와 회전계단은 한 명씩 교대 진입합니다. 보행·양보의 기하학 예시이며 낙상·접촉력·법규 적합 판정은 아닙니다.'}
updateStats=function(){v6Prior.updateStats();if(group==='crowd'&&v6Sessions.length){$('eyebrow').textContent='유입량 즉시 변경 · 기존 사람 유지 · 무한 연속 재생';$('crowdDemandText').textContent=(+$('crowdDemand').value).toFixed(1)+'× · '+Math.round(+$('crowdDemand').value*60)+'명/분';$('v4CrowdRun').hidden=!dirty;$('status').textContent='이전의 반복 횟수는 난수 시드별 통계 반복이었습니다. 현재는 동일 시드의 3/6조건을 계속 실행합니다. 최근 30초 결과는 유입 변경 전후가 섞일 수 있습니다.';$('note').textContent='슬라이더는 앞으로 도착하는 사람 수만 바꿉니다. 이미 통로에 있는 사람과 대기열을 유지하며 시간과 ID를 초기화하지 않습니다. 5%는 연속 유입 20명 중 1명이 반대편을 선택하는 가정입니다.';}if(group==='home')v6HomeStats();if(group==='lift'){$('status').textContent='오른쪽 대기 → 하차 먼저 → 고층부터 탑승해 뒤쪽으로 → 저층은 출입구 가까이. 목적층 안내는 승객의 탑승 순서와 자리를 바꾸는 운영 대안입니다.';$('note').textContent='방향 안내만으로는 최종 자리가 그대로여서 하차 장면이 같을 수 있습니다. 목적층 안내는 고층을 먼저 안쪽에, 저층을 나중에 문 가까이에 배치합니다. 화살표는 복도의 진입 유도이며 카 안 회전을 강제하지 않습니다.';}}
function v6Layout(){if(document.body)document.body.dataset.v6Group=group;$('time').hidden=group==='crowd'||group==='lift';$('timeText').hidden=group==='lift';$('heat').hidden=group==='lift';$('v4CrowdRun').hidden=group!=='crowd'||!dirty;for(let id of ['v4LiftPolicy','v4ShowLobby','v4ShowFull','v4LiftRun','v5CompareOn']){let e=$(id);e.hidden=true;if(id==='v4LiftPolicy'&&e.previousElementSibling)e.previousElementSibling.hidden=true;}if($('v5CompareOn').parentElement)$('v5CompareOn').parentElement.hidden=true;$('v5CompareOn').checked=true;if(group==='lift')v5Show();}
setGroup=function(g){if(v6LiftTimer){clearTimeout(v6LiftTimer);v6LiftTimer=null}let selection=v4Selected;v6Prior.setGroup(g);if(group==='crowd'&&v6Sessions.length){v4Selected=Math.min(selection,v6Sessions.length-1);let differs=JSON.stringify(v6Sessions.at(-1).obstacles)!==JSON.stringify(obstacles);dirty=differs;time=v6Sessions[0].engine.getTime();v4FillReplay();rebuild()}v6Layout();updateStats();if(group==='lift'&&v4LiftStale)v6LiftTimer=setTimeout(()=>{if(group==='lift')v4Run('lift')},450)};
function v6BusCount(){let ps=people().filter(p=>p.p[1]>=0&&p.state!=='queue'&&p.state!=='gone'),total=ps.length,front=ps.filter(p=>p.p[0]>=5.25).length;return{total,front,rear:total-front}}
draw=function(){v6Prior.draw();if(group==='crowd'&&v6Sessions.length){let m=stats();$('hud').textContent=v6Sessions[v4Selected].label+'\n'+time.toFixed(1)+'초 · 현재 통로 '+m.inside+' / 대기 '+m.outside+'명\n유입 '+Math.round(+$('crowdDemand').value*60)+'명/분 · 기존 보행자 유지';$('timeText').textContent=time.toFixed(1)+'초 · '+(playing?'연속 재생':'일시정지');if(v6Before){let now=v6Summary()[v4Selected],before=v6Before[v4Selected];$('v6LiveNote').textContent='변경 직전 대비: 속도 '+(now.mean_population_net_speed.mean-before.mean_population_net_speed.mean).toFixed(2)+'m/s · 밀도 '+(now.average_density.mean-before.average_density.mean).toFixed(2)+'명/㎡ · 최근30초';}}if(group==='bus'){let count=v6BusCount();let rr=motionResult(),phase=rr.series[K.clamp(Math.floor(time/rr.dt_frame),0,rr.series.length-1)];$('hud').textContent=(phase[7]==='travel'?'주행 중 · 문 닫힘 · 2초 전환':'정류장 '+phase[6]+'/6 · '+({opening:'문 여는 중',open:'승하차 중',closing:'문 닫는 중'}[phase[7]]||phase[7]))+'\n현재 탑승 총 '+count.total+'명 = 앞 '+count.front+' + 뒤 '+count.rear+'명';let m=stats(),r=motionResult(),row=r.series[K.clamp(Math.floor(time/r.dt_frame),0,r.series.length-1)];cards([[count.total+'명','현재 탑승 총인원'],[count.front+' / '+count.rear+'명','앞 / 뒤 탑승'],[row[3]+'명','현재 정류장 대기'],[row[6]+' / 6회','정차 횟수']]);}if(group==='home')v6HomeStats();};
// Replace the old shifted rail with rails at the actual inner and outer boundaries.
extraMesh=function(m,ps){if(group==='home'){let g=StairV6.objects(v5Stairs,$('v5StairKind').value);for(let rail of g.rails)for(let i=1;i<rail.points.length;i++){let a=rail.points[i-1],b=rail.points[i];m.beam([a[0],a[1],a[2]+.9],[b[0],b[1],b[2]+.9],rail.name.startsWith('central')?.022:.014,rail.color);if(i%2===1)m.beam(b,[b[0],b[1],b[2]+.9],.015,rail.color);}return}v6Prior.extraMesh(m,ps)};
v5BuildStairs=function(){v5Stairs=StairV6.solve({width:+$('v5SW').value,depth:+$('v5SD').value,height:+$('v5SH').value,clearWidth:+$('v5SB').value});let kind=$('v5StairKind').value,g=StairV6.objects(v5Stairs,kind),a=g.metrics;scene={id:'H6',group:'home',title:'계단 배치',variant:kind,objects:g.objects,route:g.route,metrics:a};rebuild();$('time').max=179.8;updateStats()};
for(let id of ['v6StairCount','v6StairFlow'])$(id).oninput=()=>{time=0;updateStats()};$('v6StairFlow').onchange=$('v6StairFlow').oninput;
function v6LiftFloor(mesh,policy,spec){if(policy==='random')return;function arrow(a,b){mesh.beam(a,b,.025,'#c39336');let angle=Math.atan2(b[1]-a[1],b[0]-a[0]);for(let s of [-1,1])mesh.beam(b,[b[0]-.18*Math.cos(angle)+s*.1*Math.sin(angle),b[1]-.18*Math.sin(angle)-s*.1*Math.cos(angle),.02],.025,'#c39336')};arrow([spec.width+.3,-.9,.02],[spec.width/2,-.9,.02]);arrow([spec.width/2,-.9,.02],[spec.width/2,-.2,.02]);if(policy==='ccw_dest'){mesh.box([.02,.02,.002],[spec.width-.04,.32,.008],'#dfb292');mesh.box([.02,spec.depth-.34,.002],[spec.width-.04,.32,.008],'#8bbfb8')}}
const v6LiftInputs=['v4LiftN','v4Compliance','v4Headway','v4Hesitation','v4WalkSpeed','v4Depth','liftBody','liftGap','liftMass','liftBag'];for(let id of v6LiftInputs){let old=$(id).oninput;$(id).oninput=()=>{old?.();if(v6LiftTimer)clearTimeout(v6LiftTimer);v6LiftTimer=setTimeout(()=>{if(group==='lift')v4Run('lift')},450)}}
const v6Variant=$('variant').onchange;$('variant').onchange=()=>{v6Variant();v6Layout();if(group==='lift'){if(v6LiftTimer)clearTimeout(v6LiftTimer);v6LiftTimer=setTimeout(()=>{if(group==='lift')v4Run('lift')},450)}};
tick=function(stamp){let dt=lastStamp?Math.min(.25,(stamp-lastStamp)/1000):0;lastStamp=stamp;if(playing){let elapsed=dt*(+$('playSpeed').value||1);if(group==='crowd'&&!dirty&&v6Sessions.length){for(let s of v6Sessions)s.engine.advance(elapsed);time=v6Sessions[0].engine.getTime();v6ChartClock+=elapsed;if(v6ChartClock>=.7){v6ChartClock=0;v4Strip();table()}}else if(group!=='crowd'){time+=elapsed;if(time>+$('time').max)time=0}draw()}requestAnimationFrame(tick)};
document.querySelectorAll('[data-group]').forEach(b=>{if(b.dataset.group==='home')b.textContent='계단 배치';if(['crowd','bus','lift','home'].includes(b.dataset.group))b.onclick=()=>setGroup(b.dataset.group)});
$('downloadResult').onclick=()=>saveJSON(group==='crowd'?{model:'continuous grid / rolling30s',time,conditions:v6Sessions.map(s=>({label:s.label,metrics:s.engine.metrics(),config:s.engine.getConfig()}))}:group==='home'?{study:v5Stairs,motion:v6StairResult().metrics}:group==='bus'?{metrics:stats(),current:v6BusCount()}:v4LiftStudy,'microspace_v6_result.json');
Object.assign(window.microspace,{version:6,setGroup,draw,people,stats,getMotion:motionResult,getCrowdStudy:()=>({conditions:v6Sessions.map(s=>({label:s.label})),summaries:v6Summary(),metrics:v6Sessions.map(s=>s.engine.metrics())}),getLiveSessions:()=>v6Sessions,getStairStudy:()=>v5Stairs,setDemand:v6Rate,advanceCrowd:seconds=>{for(let s of v6Sessions)s.engine.advance(seconds);time=v6Sessions[0].engine.getTime();updateStats()},getBusCount:v6BusCount,renderSnapshot:()=>{let ps=group==='crowd'&&dirty?[]:people(),m=new K.Mesh();extraMesh(m,ps);drawDensity(m,ps);for(let p of ps)K.person(m,p);return{static:staticMesh.data,dynamic:m.data,matrix:Array.from(cam.matrix),people:ps}}});
v6StartCrowd(40);v6Layout();updateStats();


/* Static public route bootstrap: full-page links remain valid on GitHub project subpaths. */
const PUBLIC_ROUTE={crowd:'crowd',bus:'bus',lift:'elevator',home:'stairs'};
const publicInitial=window.MICROSPACE_INITIAL_GROUP||'crowd';
if(publicInitial!==group)setGroup(publicInitial);
document.querySelectorAll('[data-group]').forEach(link=>{let slug=PUBLIC_ROUTE[link.dataset.group];if(slug){link.onclick=null;link.href='../'+slug+'/';link.setAttribute?.('aria-current',link.dataset.group===group?'page':'false')}});
window.microspace.publicBuild=true;
